window.ScripturaLexicons.BDAG_PART_0302 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0302-01\" data-source=\"BDAG\" data-search=\"προμελετάω verbo preparar de antemão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προμελετάω</td><td>verbo</td><td>preparar de antemão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0302-02\" data-source=\"BDAG\" data-search=\"προμεριμνάω verbo preocupar-se de antemão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προμεριμνάω</td><td>verbo</td><td>preocupar-se de antemão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0302-03\" data-source=\"BDAG\" data-search=\"προνηστεύω verbo jejuar de antemão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προνηστεύω</td><td>verbo</td><td>jejuar de antemão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0302-04\" data-source=\"BDAG\" data-search=\"προνοέω verbo considerar, cuidar, prover BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προνοέω</td><td>verbo</td><td>considerar, cuidar, prover</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0302-05\" data-source=\"BDAG\" data-search=\"πρόνοια, ας, ἡ substantivo feminino previsão, previdência, providência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρόνοια, ας, ἡ</td><td>substantivo feminino</td><td>previsão, previdência, providência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0302-06\" data-source=\"BDAG\" data-search=\"προοδοιπορέω verbo ir adiante, ter morrido anteriormente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προοδοιπορέω</td><td>verbo</td><td>ir adiante, ter morrido anteriormente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0302-07\" data-source=\"BDAG\" data-search=\"προοδοιπόρος, ον adjetivo que vai adiante, precursor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προοδοιπόρος, ον</td><td>adjetivo</td><td>que vai adiante, precursor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0302-08\" data-source=\"BDAG\" data-search=\"πρόοιδα verbo saber de antemão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρόοιδα</td><td>verbo</td><td>saber de antemão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0302-09\" data-source=\"BDAG\" data-search=\"προοικονομέω verbo dispor de antemão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προοικονομέω</td><td>verbo</td><td>dispor de antemão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0302-10\" data-source=\"BDAG\" data-search=\"προοράω verbo prever, ver anteriormente, ter diante dos olhos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προοράω</td><td>verbo</td><td>prever, ver anteriormente, ter diante dos olhos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0302-11\" data-source=\"BDAG\" data-search=\"προορίζω verbo determinar de antemão, predeterminar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προορίζω</td><td>verbo</td><td>determinar de antemão, predeterminar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0302-12\" data-source=\"BDAG\" data-search=\"προπάσχω verbo sofrer anteriormente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προπάσχω</td><td>verbo</td><td>sofrer anteriormente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0302-13\" data-source=\"BDAG\" data-search=\"προπάτωρ, ορος, ὁ substantivo masculino antepassado, ancestral BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προπάτωρ, ορος, ὁ</td><td>substantivo masculino</td><td>antepassado, ancestral</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0302-14\" data-source=\"BDAG\" data-search=\"προπέμπω verbo acompanhar, auxiliar na viagem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προπέμπω</td><td>verbo</td><td>acompanhar, auxiliar na viagem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0302-15\" data-source=\"BDAG\" data-search=\"προπετής, ές adjetivo impetuoso, precipitado, temerário BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προπετής, ές</td><td>adjetivo</td><td>impetuoso, precipitado, temerário</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0302-16\" data-source=\"BDAG\" data-search=\"προπορεύομαι verbo ir adiante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προπορεύομαι</td><td>verbo</td><td>ir adiante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0302-17\" data-source=\"BDAG\" data-search=\"πρός preposição para, junto de, em relação a, com, contra BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρός</td><td>preposição</td><td>para, junto de, em relação a, com, contra</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0302-18\" data-source=\"BDAG\" data-search=\"προσάββατον, ου, τό substantivo neutro véspera do sábado, sexta-feira BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσάββατον, ου, τό</td><td>substantivo neutro</td><td>véspera do sábado, sexta-feira</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0302-19\" data-source=\"BDAG\" data-search=\"προσαγορεύω verbo saudar, chamar, designar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσαγορεύω</td><td>verbo</td><td>saudar, chamar, designar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0302-20\" data-source=\"BDAG\" data-search=\"προσάγω verbo conduzir, apresentar, aproximar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσάγω</td><td>verbo</td><td>conduzir, apresentar, aproximar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0302-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προμελετάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προμελετάω</span> (Aristoph.; Ps.-X., Rep. Ath. 1, 20; Pla. et al.; Philo, Fuga 36) preparar-se de antemão mediante reflexão cuidadosa e atenção, exercitar-se de antemão, preparar-se (do ensaio de um discurso Aristoph., Eccl. 116) seguido de inf. (B-D-F §392, 2) <span class=\"greek\">πρ</span>. <span class=\"greek\">ἀπολογηθῆναι</span> preparar a própria defesa (para comparecimento perante um tribunal) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:14</a>.—DELG s.v. <span class=\"greek\">μέλω</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0302-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προμεριμνάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προμεριμνάω</span> preocupar-se de antemão, inquietar-se ou estar ansioso de antemão, seguido de interrogativa indireta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:11</a>.—DELG s.v. <span class=\"greek\">μέριμνα</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0302-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προνηστεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προνηστεύω</span> 1.º aor. <span class=\"greek\">προενήστευσα</span> (Hdt. 2, 40; Hippocr. ed. Littré; VII 412; VIII 178) jejuar de antemão D 7:4.—DELG s.v. 1 <span class=\"greek\">νῆστις</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0302-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προνοέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προνοέω</span> 1.º aor. 3.ª sg. <span class=\"greek\">προενόησεν</span> Wsd 13:16, inf. <span class=\"greek\">προνοῆσαι</span> (Just., D. 116, 2); perf. médio 2.ª pl. <span class=\"greek\">προνενόησθε</span> (Ath. 1, 3); aor. médio-pass. imper. 2.ª sg. <span class=\"greek\">προνοήθητι</span> 2 Macc 14:9, subj. 3.ª sg. <span class=\"greek\">προνοηθῇ</span> Da 11:37 (Hom. et al.; ins, pap, LXX; Just.; Tat. 2, 2; Ath.) ‘pensar de antemão em algo’</p><p class=\"entry-text\">① refletir cuidadosamente sobre, considerar, levar em consideração, ter em conta, seguido de gen. (Jos., Ant. 1, 53 <span class=\"greek\">ἀρετῆς</span>) <span class=\"greek\">ἁγνείας</span> Pol 5:3. <span class=\"greek\">τοῦ</span> <span class=\"greek\">καλοῦ</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">θεοῦ</span> 6:1. Com acus. <span class=\"greek\">καλὰ</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">κυρίου</span> (cf. Pr 3:4 para este caso e Pol 6:1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:21</a>. Seguido de <span class=\"greek\">πῶς</span> a fim de que D 12:4.—A voz média no mesmo sentido (Thu.+; ins, pap, LXX, Philo; Jos., Ant. 9, 3; 19, 309 al.; Just., A I, 44, 11; Ath. 1, 3), com acus. (X., Mem. 4, 3, 12) <span class=\"greek\">καλὰ</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">ἀνθρώπων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:17</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:21</a> v.l.</p><p class=\"entry-text\">② pensar de antemão com solicitude, cuidar de, prover para alguém/algo, com gen. (X.+; Maximus Tyr. 5, 4c [<span class=\"greek\">προνοεῖ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὅλου</span>]; ins [p. ex. New Docs 7, 234 n.º 10, 23], pap; Wsd 13:16; Philo, Virt. 216; Just., D. 1, 4 al.) <span class=\"greek\">τῶν</span> <span class=\"greek\">ἰδίων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μάλιστα</span> <span class=\"greek\">οἰκείων</span> os seus e especialmente os membros de sua família <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:8</a> (Horapollo 2, 108 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οἰκείων</span> <span class=\"greek\">προνοούμενος</span>; New Docs 8, 113–16); a v.l. apresenta a voz média no mesmo sentido (Horap., loc. cit. <span class=\"greek\">προνοούμενος</span> <span class=\"greek\">ἑαυτοῦ</span>).—M-M. DELG s.v. <span class=\"greek\">νόος</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0302-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόνοια, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρόνοια</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πρόνοος</span> ‘prudente’; Aeschyl., Ag. 683, Ch. 606; Hdt.+; ins, pap, LXX; TestSol 1:13 D; EpArist, Philo, Joseph., apolog. exc. Mel.) planejamento cuidadoso para atender a uma necessidade, previdência, previsão, providência</p><p class=\"entry-text\">ⓐ de Deus, esp. com referência à beneficência divina (Trag.; Hdt, 3, 108, 1; X., Mem. 1, 4, 6; 4, 3, 6; Pla., Tim. 30b; 44c; Polyb. 23, 17, 10; Posidonius em Diog. L. 7, 138; Diod S 1, 1, 3; 3, 57, 5; 4, 47, 1 <span class=\"greek\">θεῶν</span> <span class=\"greek\">πρόνοια</span> al.; Diog. L. 3, 24; Plut., Mor. 425f; 436d; Achilles Tat. 7, 10, 1; Herm. Wr. 1, 19; 12, 14; 21; em Stob. p. 514, 24; 516, 5 Sc. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἄνω</span> <span class=\"greek\">πρόνοια</span> p. 418, 28 Sc.; SIG 700, 29 [117 a.C.] <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">προνοίας</span>; POslo 148 [II/I a.C.] <span class=\"greek\">τῇ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεῶν</span> <span class=\"greek\">προνοίᾳ</span>; POxy 1682, 6; SJCh 78, 5; Wsd; 3 e 4 Macc; EpArist 201; SibOr 5, 227; 323. Fílon escreveu uma obra intitulada <span class=\"greek\">Περὶ</span> <span class=\"greek\">προνοίας</span> [Eus., PE 2, 18, 6; 7, 20, 9; 8, 13, 7]; Jos., Bell. 3, 391; 7, 453, Ant. 2, 60; 349 al.; Ar. 1, 1; Just.; Tat. 2, 1; Ath.; cf. Cicero, De Natura Deorum 2, 73f; New Docs 3, 143f numerosas referências papirológicas) 1 Cl 24:5; AcPlCor 2:19. Com <span class=\"greek\">σοφία</span> (Ael. Aristid. 36, 123 K.=48 p. 488 D.) Hv 1, 3, 4 (Leutzsch, Hermas 391 n. 119).</p><p class=\"entry-text\">ⓑ de seres humanos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:2</a>. <span class=\"greek\">πρόνοιαν</span> <span class=\"greek\">ποιεῖσθαί</span> <span class=\"greek\">τινος</span> tomar providências para algo, ter solicitude por algo ou preocupar-se com algo (Demosth.; Polyb.; Dionys. Hal. 10, 1; Plut.; SIG 734, 5 <span class=\"greek\">τᾶς</span> <span class=\"greek\">εὐσεβείας</span> e freq. de pessoas distinguidas por <span class=\"greek\">ἀρετή</span> ou excelência [v. índice]; POxy 899, 17; PFlor 2, 207; PLond 1912 [carta de Cláudio], 103 [41 d.C.] e freq.; Da 6:19; EpArist 80; Jos., C. Ap. 1, 9, Vi. 62) <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">πρόνοιαν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ποιεῖσθε</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἐπιθυμίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:14</a> (Philo, Ebr. 87 <span class=\"greek\">σαρκῶν</span> <span class=\"greek\">ποιεῖσθαι</span> <span class=\"greek\">πρόνοιαν</span>). <span class=\"greek\">ἑνὸς</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἐποιήσατο</span> <span class=\"greek\">πρ</span>., <span class=\"greek\">τοῦ</span> <span class=\"greek\">μηδὲν</span> … <span class=\"greek\">παραλιπεῖν</span> (Marcos) preocupou-se primordialmente … em nada omitir ou tomou providências para uma coisa, omitir … Papias (2:15).—JAmann, D. Zeusrede d. Ail. Arist. ’31, 73ff.—Renehan ’75. Larfeld I 499. New Docs 8, 109–116. 1263–66. DELG s.v. <span class=\"greek\">νόος</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0302-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προοδοιπορέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προοδοιπορέω</span> 1.º aor. part. <span class=\"greek\">προοδοιπορήσας</span> (Lucian, Hermot. 27; Diog. L. 7, 176; Jos., Ant. 3, 2; Mel., P. 54, 396) primariamente ‘viajar, ir adiante’. Eufemisticamente (como elemento de consolação que sugere que os falecidos têm algum domínio sobre seu destino) por morrer antes do momento presente <span class=\"greek\">οἱ</span> <span class=\"greek\">προοδοιπορήσαντες</span> <span class=\"greek\">πρεσβύτεροι</span> 1 Cl 44:5; <span class=\"greek\">τῶν</span> <span class=\"greek\">οὕ</span>]<span class=\"greek\">τως</span> <span class=\"greek\">προοδυπορ</span>[<span class=\"greek\">ούντω</span>]<span class=\"greek\">ν</span>=<span class=\"greek\">προοδοιπορούντων</span> (restauração por Testuz) aqueles (falsos mestres) que assim vão adiante dele (para o juízo final) AcPlCor 2:37. V. <span class=\"greek\">κοιμάω</span> 2.—DELG s.v. <span class=\"greek\">ὁδός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0302-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προοδοιπόρος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προοδοιπόρος</span>, <span class=\"greek\">ον</span> (tardio e raro; v. verbete anterior e Hesychius s.v. <span class=\"greek\">ὁδουρός</span>) que vai adiante, substantivado <span class=\"greek\">ὁ</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">προοδοιπόρος</span>, do vício como (<span class=\"greek\">ἡ</span>) <span class=\"greek\">προοδοιπόρος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτιῶν</span> <span class=\"greek\">ἡμῶν</span> o precursor de nossos pecados 2 Cl 10:1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0302-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόοιδα</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρόοιδα</span> (Hdt. et al.; Epict. 2, 10, 5; PSI 349, 8 [III a.C.]; Wsd 19:1; 4 Macc 4:25; Just., D. 103, 4; Ath. 21, 5) perf. (com sentido de presente), part. <span class=\"greek\">προειδώς</span>; mais-que-perf. <span class=\"greek\">προῇδειν</span> saber de antemão/anteriormente com gen. (Menand., Peric. 472 S. [222 Kö.]; Polyb. 5, 13, 5 <span class=\"greek\">τὸ</span> <span class=\"greek\">μέλλον</span>; Herodian 7, 1, 9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:31</a> v.l.; IPhld 7:2 v.l. (v. Bihlmeyer ad loc.). Seguido de acus. e inf. 1 Cl 43:6.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0302-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προοικονομέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προοικονομέω</span> (Aristot. et al.; Joseph.) dispor de antemão/anteriormente, com acus. de coisa e dat. de pessoa <span class=\"greek\">Χριστὸν</span> <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">προοικονομοῦντα</span> <span class=\"greek\">Παύλῳ</span> Cristo Jesus, que zelava por Paulo AcPl Ha 7, 24.—DELG s.v. <span class=\"greek\">οἶκος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0302-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προοράω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προοράω</span> (Hdt. et al.; ins, pap, LXX, JosAs 23:8; Philo, Joseph.) 2.º aor. <span class=\"greek\">προεῖδον</span> (Hom. et al.); perf. <span class=\"greek\">προεώρακα</span>; imperf. médio <span class=\"greek\">προορώμην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:25</a> (sobre esta forma B-D-F §66, 2; Mlt-H. 190); aor. pass. part. neutro <span class=\"greek\">προοραθέν</span> (Mel., P. 57, 418 Ch.) (Hdt., Thu., X. et al. em vários sentidos).</p><p class=\"entry-text\">① ver de antemão, prever, com vistas ao futuro <span class=\"greek\">τὶ</span> (X., Cyr. 2, 4, 21 <span class=\"greek\">τοῦτο</span> <span class=\"greek\">προϊδὼν</span> <span class=\"greek\">ὡς</span>; Jos., Ant. 10, 142; JosAs 23:8) ITr 8:1. Seguido de <span class=\"greek\">ὅτι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:8</a>. Em uso absoluto (Jos., Bell. 2, 619) <span class=\"greek\">προϊδὼν</span> <span class=\"greek\">ἐλάλησεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:31</a>.</p><p class=\"entry-text\">② ver em momento anterior ao presente, ver anteriormente <span class=\"greek\">ἦσαν</span> <span class=\"greek\">προεωρακότες</span> <span class=\"greek\">Τρόφιμον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πόλει</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">αὐτῷ</span> tinham visto anteriormente Trófimo na cidade com (Paulo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:29</a>. O tempo perfeito e o sentido temporal de <span class=\"greek\">προ</span>- fornecem os elementos básicos deste sentido.</p><p class=\"entry-text\">③ voz média: ter diante dos olhos, ver diante de si, com acus. (Menand., Peric. 132 S. [12 Kö.]; SIG 569, 13; UPZ 42, 22 [162 a.C.]; Philo) <span class=\"greek\">τινά</span> alguém <span class=\"greek\">προορώμην</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span> <span class=\"greek\">ἐνώπιόν</span> <span class=\"greek\">μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:25</a> (Ps 15:8).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0302-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προορίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προορίζω</span> 1.º aor. <span class=\"greek\">προώρισα</span>, pass. <span class=\"greek\">προωρίσθην</span> (Demosth. 31, 4 codd.; Heliod. 7, 24, 4; TestSol 12:3; Sopater Rhet. [V d.C.]: Rhet. Gr. V p. 152, 20; vários papiros do VI d.C. em uso não cristão) decidir de antemão, predeterminar, de Deus (Iren. 2, 33, 5 [Harv. I 380, 5]) <span class=\"greek\">τινά</span> alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:30</a>. Seguido de acus. com inf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:28</a>. Seguido de <span class=\"greek\">εἰς</span> final: <span class=\"greek\">τὶ</span> algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:7</a>; <span class=\"greek\">τινά</span> alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:5</a>. <span class=\"greek\">τινά</span> <span class=\"greek\">τι</span> alguém como algo, para ser algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:29</a>. Pass. seguido de inf. IEph ins Seguido de <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">εἶναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:11</a> (12).—RLiechtenhan, D. göttl. Vorherbestimmung bei Pls u. in d. posidonianischen Philosophie 1922; HBraun, Qumran u. d. NT II, ’66, 243–50. V. também <span class=\"greek\">προγινώσκω</span>.—DELG s.v. <span class=\"greek\">ὅρος</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0302-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προπάσχω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προπάσχω</span> 2.º aor. <span class=\"greek\">προέπαθον</span> (Soph., Hdt.+; Appian, Liby. 51 §223; 52 §225; Jos., Vi. 250) sofrer anteriormente <span class=\"greek\">προπαθόντες</span> depois de já termos sofrido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:2</a>.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0302-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προπάτωρ, ορος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προπάτωρ</span>, <span class=\"greek\">ορος</span>, <span class=\"greek\">ὁ</span> (Pind., Hdt.+; Cass. Dio 44, 37; Lucian, Alex. 43; Ps.-Plut., Mor. 106f; OGI 446, 3; PGiss. 25, 16 [II d.C.]; 3 Macc 2:21 [de Deus]; TestAbr A 8 p. 85, 28 [Stone p. 18, 28]; TestLevi 9:1; Philo, Op. M. 145; Jos., Ant. 4, 26; 19, 123; Just., A I, 32, 3 e 14 <span class=\"greek\">Ἰούδας</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">προπάτωρ</span> <span class=\"greek\">Ἰουδαίων</span>, <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">οὗ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">Ἰουδαῖοι</span> <span class=\"greek\">καλεῖσθαι</span> <span class=\"greek\">ἐσχήκασι</span>=Judá era o antepassado dos judeus, e foi dele que passaram a ser chamados judeus).</p><p class=\"entry-text\">① fundador originário de uma família, antepassado, de Abraão como fundador ancestral (Jos., Bell. 5, 380) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:1</a> (os cínicos chamam Diógenes de <span class=\"greek\">προπάτωρ</span>: ADieterich, E. Mithrasliturgie 1903, p. 161, 1).</p><p class=\"entry-text\">② fundador arquetípico, ancestral primordial <span class=\"greek\">ὁ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὅλ</span>]<span class=\"greek\">ων</span> <span class=\"greek\">δεσπότης</span> <span class=\"greek\">ο</span>[<span class=\"greek\">ὐκ</span> <span class=\"greek\">ἔστ</span>]<span class=\"greek\">ι̣</span> (<span class=\"greek\">πατὴρ</span>) <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">προπά̣</span>[<span class=\"greek\">τωρ</span> <span class=\"greek\">κτλ</span>.] Ox 1081 36–38//SJCh 90, 17 (v. WTill TU 60, 5 [’55] p. 57).—DELG s.v. <span class=\"greek\">πατήρ</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0302-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προπέμπω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προπέμπω</span> imperf. <span class=\"greek\">προέπεμπον</span>; fut. 3.ª pl. <span class=\"greek\">προπέμψουσιν</span> Judth 10:15; 1.º aor. <span class=\"greek\">προέπεμψα</span>, pass. <span class=\"greek\">προεπέμφθην</span> (Hom. et al.; ins, pap, LXX; TestSol 22:16 P; JosAs 22:7; Ar. [Milne p. 76 linha 38]; Just., D. 19, 4) ‘enviar’.</p><p class=\"entry-text\">① conduzir alguém que tem em vista um destino, acompanhar, escoltar (Soph., Hdt.+; PFlor 206, 2; LXX; JosAs; Jos., Bell. 2, 631, Ant. 20, 50; Just.) <span class=\"greek\">προέπεμπον</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλοῖον</span> acompanharam-no até o navio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:38</a>. <span class=\"greek\">ἕως</span> <span class=\"greek\">ἔξω</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span> escoltar para fora da cidade 21:5.</p><p class=\"entry-text\">② auxiliar alguém a realizar uma viagem, encaminhá-lo em sua viagem com alimentos, dinheiro, providenciando companheiros, meios de transporte etc. (1 Macc 12:4; 1 Esdr 4:47; EpArist 172) <span class=\"greek\">τινά</span> alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:11</a>. Com <span class=\"greek\">δέχεσθαι</span> Pol 1:1. <span class=\"greek\">σπουδαίως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:13</a>. <span class=\"greek\">ἀξίως</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/3JN.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">3J 6</a>. Com indicação do destino <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐὰν</span> <span class=\"greek\">πορεύωμαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:6</a>. Pass. com <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:3</a>. Também com indicação do destino: <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Ἰουδαίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:16</a>; <span class=\"greek\">ἐκεῖ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:24</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0302-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προπετής, ές</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προπετής</span>, <span class=\"greek\">ές</span> (<span class=\"greek\">πρό</span>, <span class=\"greek\">πίπτω</span>) gen. <span class=\"greek\">οῦς</span> (Pind.+), lit. ‘que cai para baixo ou para diante’; em nossa literatura somente fig., relativo a ser impetuoso, precipitado, temerário, irrefletido (Isocr., Pla.; Appian, Bell. Civ. 3, 43 §176; et al.; Pr 10:14; 13:3; Sir 9:18; Jos., Ant 5, 106, Vi. 170) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:4</a>. Com <span class=\"greek\">αὐθάδης</span> 1 Cl 1:1. <span class=\"greek\">μηδὲν</span> <span class=\"greek\">π</span>. <span class=\"greek\">πράσσειν</span> nada fazer precipitadamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:36</a> (escólio sobre Soph., Aj. 32 p. 5 <span class=\"greek\">μὴ</span> <span class=\"greek\">προπετές</span> <span class=\"greek\">τι</span> <span class=\"greek\">πράσσειν</span>; Menand., Peric. 1017 S. [439 Kö.] <span class=\"greek\">προπετὲς</span> <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">μηδέ</span>; 1019 S. [441 Kö.] <span class=\"greek\">τὶ</span> <span class=\"greek\">πράξω</span> <span class=\"greek\">προπετές</span>; Jos., Ant. 15, 82).—DELG s.v. <span class=\"greek\">πίπτω</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0302-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προπορεύομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προπορεύομαι</span> fut. <span class=\"greek\">προπορεύσομαι</span> (X. et al.; POxy 1144, 3; 5; 9 [I/II d.C.]; LXX) ir adiante com gen. de pessoa (Aristot. 844b, 5; LXX) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:40</a> (Ex 32:1, 23). <span class=\"greek\">ἐνώπιόν</span> <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.76\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:76</a> revela influência do uso do AT, embora a v.l. <span class=\"greek\">πρὸ</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">τινός</span> também se encontre na LXX.—A metáfora <span class=\"greek\">προπορεύσεται</span> <span class=\"greek\">ἔμπροσθέν</span> <span class=\"greek\">σου</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">δικαιοσύνη</span> B 3:4 (Is 58:8) também tem antecedentes no AT (mas cf. X., Cyr. 4, 2, 23 <span class=\"greek\">πορεύεσθε</span> <span class=\"greek\">ἔμπροσθεν</span>).—DELG s.v. <span class=\"greek\">πόρος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0302-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρός</h1><div class=\"entry-meta\"><span>preposição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρός</span> prep. que exprime direção ‘do lado de’, ‘na direção de’: com gen. ‘de’, dat. ‘junto de’, ou acus. (o uso mais freq. em nossa literatura) ‘para’ (v. a bibliografia s.v. <span class=\"greek\">ἀνά</span>, início) (Hom.+).</p><p class=\"entry-text\">① com gen. (pseudepígr. somente TestSol 10:4 C; apolog. exc. Ar.) marcador de direção ou aspecto a partir do qual algo é determinado, em benefício de, vantajoso para (Thu. 3, 59, 1 <span class=\"greek\">οὐ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὑμετέρας</span> <span class=\"greek\">δόξης</span> <span class=\"greek\">τάδε</span>; Hdt. 1, 75; Dionys. Hal. 10, 30, 5; Diod S 18, 50, 5; Lucian, Dial. Deor. 20, 3; Mel., HE 4, 26, 8; Ath. 36, 1; B-D-F §240; Rob. 623f) <span class=\"greek\">οἱ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">ζωῆς</span> <span class=\"greek\">μαζοί</span> os seios que dão vida 1 Cl 20:10. <span class=\"greek\">πρ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">σωτηρίας</span> no interesse da segurança <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:34</a> (<span class=\"greek\">πρὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ς</span>. como em Jos., Ant. 16, 313).</p><p class=\"entry-text\">② com dat. (pseudepígr. somente TestSol 6:4 D; TestAbr [v. abaixo]; JosAs 19:1.—Just.; Mel., HE 4, 26, 7; Ath., R. 22 p. 75, 10) marcador de estreiteza de relação ou proximidade</p><p class=\"entry-text\">ⓐ de lugar: perto de, em, junto de (Hom. et al., inclusive Aristarch. Samos 398, 20; LXX; TestSol 6:4 D; Jos., Ant 8, 349; 381) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:11</a>; ao redor de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:13</a>. <span class=\"greek\">πρ</span>. <span class=\"greek\">τῇ</span> <span class=\"greek\">θύρᾳ</span> <span class=\"greek\">ἑστηκέναι</span> estar de pé à porta (Menand., Fgm. 420, 1; 830 K.=352, 1; 644 Kö.; JosAs 19:1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:16</a>; cf. 20:11. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πύλῃ</span> GJs 4:4; <span class=\"greek\">ἐγγίζοντος</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">τῇ</span> <span class=\"greek\">καταβάσει</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄρους</span> quando ele se aproximou da encosta do monte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:37</a> (v. <span class=\"greek\">κατάβασις</span>). <span class=\"greek\">πρ</span>. <span class=\"greek\">τῇ</span> <span class=\"greek\">κεφαλῇ</span>, <span class=\"greek\">τοῖς</span> <span class=\"greek\">ποσίν</span> à cabeceira, aos pés <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:12</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">ταῖς</span> <span class=\"greek\">ῥίζαις</span> as partes próximas das raízes Hs 9, 1, 6; 9, 21, 1. Em designações geográficas <span class=\"greek\">Μαγνησία</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">Μαιάνδρῳ</span> Magnésia junto ao Meandro IMagnMai ins.—(Cf. o uso temporal: <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἑσπέρᾳ</span> <span class=\"greek\">ἐστίν</span> ocorre ao anoitecer TestAbr B 2 p. 106, 7 [Stone p. 60]; cf. Just., D. 105, 3 e 5; 142, 1.)</p><p class=\"entry-text\">ⓑ além de (Hom. et al.; Polyb., Just.; Mel., HE 4, 26, 7; Ath., R. 22 p. 75, 10; ins) <span class=\"greek\">πρὸς</span> <span class=\"greek\">τούτοις</span> (SIG 495, 105; 685, 70 e 100; 796 B, 30; 888, 35 al.; UPZ 26, 18; 25 [163 a.C.]; 2 Macc 4:9; 5:23; 9:17, 25; 14:4, esp. 12:2; Philo, Aet. M. 67 al.; Just., A I, 40, 5; D. 93, 4 al.) 1 Cl 17:1.</p><p class=\"entry-text\">③ com acus. (em toda a literatura pseudepígr. e apolog.) marcador de movimento ou orientação em direção a alguém/algo</p><p class=\"entry-text\">ⓐ de lugar, pessoa ou coisa: em direção a, para, após verbos</p><p class=\"entry-text\"><span class=\"greek\">α</span>. de ir; v. <span class=\"greek\">ἄγω</span> 5, <span class=\"greek\">ἀναβαίνω</span> 1a<span class=\"greek\">α</span>, <span class=\"greek\">ἀνακάμπτω</span> 1a, <span class=\"greek\">ἀπέρχομαι</span> 1b, <span class=\"greek\">διαβαίνω</span>, <span class=\"greek\">διαπεράω</span>, <span class=\"greek\">εἴσειμι</span>, <span class=\"greek\">εἰσέρχομαι</span> 1b<span class=\"greek\">α</span>, <span class=\"greek\">ἐκπορεύομαι</span> 1c, também <span class=\"greek\">ἐπισυνάγομαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:33</a>, <span class=\"greek\">ἔρχομαι</span> 1a<span class=\"greek\">β</span>, <span class=\"greek\">ἥκω</span> 1d et al.—<span class=\"greek\">προσαγωγὴ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πατέρα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:18</a>. <span class=\"greek\">εἴσοδος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:9a</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. de enviar; v. <span class=\"greek\">ἀναπέμπω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:7</a>, 15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:21</a>, <span class=\"greek\">ἀποστέλλω</span> 1b<span class=\"greek\">α</span>, <span class=\"greek\">πέμπω</span>.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. de movimento em geral; v. <span class=\"greek\">βληθῆναι</span> (<span class=\"greek\">βάλλω</span> 1b), <span class=\"greek\">ἐπιστρέφω</span> 1a, 4ab, <span class=\"greek\">κεῖμαι</span> 2, <span class=\"greek\">πίπτω</span> 1b<span class=\"greek\">α</span>א e ב, <span class=\"greek\">προσκολλάω</span>, <span class=\"greek\">προσκόπτω</span> 1, <span class=\"greek\">προσπίπτω</span>.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. de conduzir, guiar; v. <span class=\"greek\">ἄγω</span> 1a, <span class=\"greek\">ἀπάγω</span> 2a e 4, também <span class=\"greek\">ἕλκω</span> 2, fim <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:32</a>, <span class=\"greek\">κατασύρω</span> etc.</p><p class=\"entry-text\"><span class=\"greek\">ε</span>. de dizer, falar; v. <span class=\"greek\">ἀποκρίνομαι</span> 1, também <span class=\"greek\">δημηγορέω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:21</a>, <span class=\"greek\">εἶπον</span> 1a, <span class=\"greek\">λαλέω</span> 2a<span class=\"greek\">γ</span> e 2b, <span class=\"greek\">λέγω</span> 1b<span class=\"greek\">γ</span> et al. Em construção hebraizante <span class=\"greek\">λαλεῖν</span> <span class=\"greek\">στόμα</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">στόμα</span> falar face a face (Jer 39:4; ApcEsdr 6:6 p. 31, 10 Tdf.) 2J 12b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/3JN.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">3J 14</a> (cf. PGM 1, 39 <span class=\"greek\">τὸ</span> <span class=\"greek\">στόμα</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">στόμα</span>). <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἀλλήλους</span> uns aos outros, uns com os outros, entre si: v. <span class=\"greek\">ἀντιβάλλω</span>, <span class=\"greek\">διαλαλέω</span>, também <span class=\"greek\">διαλέγομαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:34</a>, <span class=\"greek\">διαλογίζομαι</span> 8:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:14</a>, <span class=\"greek\">εἶπον</span> 24:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:17</a>; 19:24, <span class=\"greek\">λαλέω</span>, <span class=\"greek\">λέγω</span> et al. <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἑαυτούς</span> a si mesmos, uns aos outros: v. <span class=\"greek\">διαλογίζομαι</span> 1; <span class=\"greek\">εἶπον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:35</a>; <span class=\"greek\">λέγω</span> (Ps.-Callisth. 2, 15, 7 <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ἔλεγεν</span>; Just., D. 62, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:26</a>; 16:3. <span class=\"greek\">διαθήκην</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">διέθετο</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πατέρας</span> <span class=\"greek\">ὑμῶν</span>, <span class=\"greek\">λέγων</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">Ἀβραάμ</span> Deus fez uma aliança com vossos pais, quando disse a Abraão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:25</a> (<span class=\"greek\">διατίθημι</span> 1). <span class=\"greek\">ὅρκον</span> <span class=\"greek\">ὀμνύναι</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">τινα</span> (<span class=\"greek\">ὀμνύω</span>, fim) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.73\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:73</a>.</p><p class=\"entry-text\"><span class=\"greek\">ζ</span>. de pedir, orar <span class=\"greek\">δέομαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:24</a>. <span class=\"greek\">εὔχομαι</span> (v. <span class=\"greek\">εὔχομαι</span> 1; cf. 2 Macc 9:13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:7</a>. <span class=\"greek\">προσεύχομαι</span> (cf. 1 Km 12:19; 2 Esdr 12: 4; 2 Macc 2:10) Hv 1, 1, 9. <span class=\"greek\">γνωρίζεσθαι</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:6</a> (<span class=\"greek\">γνωρίζω</span> 1).—Também após substantivos como <span class=\"greek\">δέησις</span>, <span class=\"greek\">λόγος</span> et al. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:1</a>; 15:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:18</a> al.</p><p class=\"entry-text\">ⓑ de tempo: perto de, em ou durante (determinado tempo)</p><p class=\"entry-text\"><span class=\"greek\">α</span>. denotando aproximação: para, em direção a (X., Pla. et al.) <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἑσπέραν</span> ao cair da tarde <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:29</a> (assim Just., D. 97, 1; v. <span class=\"greek\">ἑσπέρα</span>).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. de duração temporal: por <span class=\"greek\">πρὸς</span> <span class=\"greek\">καιρόν</span> por certo tempo, por algum tempo (<span class=\"greek\">καιρός</span> 1a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:5</a>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">καιρὸν</span> <span class=\"greek\">ὥρας</span> (<span class=\"greek\">καιρός</span> 1a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:17</a>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὥραν</span> por uma hora, isto é, por breve tempo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:5a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHM.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Phlm 15</a>; MPol 11:2. <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὀλίγας</span> <span class=\"greek\">ἡμέρας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:10</a>. Também <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὀλίγον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:14</a>; GJs 19:2 (<span class=\"greek\">ὀλίγος</span> 3). <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">παρόν</span> por ora <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:11</a> (<span class=\"greek\">πάρειμι</span> 1b).</p><p class=\"entry-text\">ⓒ de finalidade: (visando) a ou (esforçando-se) em direção a</p><p class=\"entry-text\"><span class=\"greek\">α</span>. com propósito consciente: para, com o fim de, em benefício de <span class=\"greek\">οὗτος</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐλεημοσύνην</span> <span class=\"greek\">καθήμενος</span> este era aquele que se sentava (e mendigava) para obter esmolas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:10</a>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἔνδειξιν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δικαιοσύνης</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:26</a>. <span class=\"greek\">τοῦτο</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">σύμφορον</span> <span class=\"greek\">λέγω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.35\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:35a</a>; cf. 35b. <span class=\"greek\">ἐγράφη</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">νουθεσίαν</span> <span class=\"greek\">ἡμῶν</span> 10:11. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:6</a>; 7:3; 11:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:12</a>.—Com acus. do inf. (Polyb. 1, 48, 5; PRyl 69, 16; BGU 226, 22; Jer 34:10; 2 Macc 4:45; TestJob 45:4; Jos., Ant. 14, 170; 15, 148 al.; Just., D. 132, 1) <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θεαθῆναι</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀνθρώποις</span> a fim de serem vistos pelos homens <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:5</a>; cf. 6:1. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κατακαῦσαι</span> <span class=\"greek\">αὐτά</span> 13:30. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐνταφιάσαι</span> <span class=\"greek\">με</span> 26:12. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀποπλανᾶν</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">δυνατὸν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἐκλεκτούς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:22</a>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀτενίσαι</span> <span class=\"greek\">υἱοὺς</span> <span class=\"greek\">Ἰσραήλ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:13</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:11a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:3</a> v.l.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. geralmente de desígnio, destino (Demetr.[?]: 722 Fgm. 7 Jac. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κάρπωσιν</span>; TestJob 42:7 <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">θυσίαν</span>; Jos., Bell. 4, 573 <span class=\"greek\">τὸ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">σωτηρίαν</span> <span class=\"greek\">φάρμακον</span>) <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">δόξαν</span> para a glória de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:20</a> (sobre <span class=\"greek\">πρὸς</span> <span class=\"greek\">δόξαν</span> cf. SIG 456, 15; 704e, 21; 3 Macc 2:9; Just., A I, 15, 10 <span class=\"greek\">μηδὲν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">δόξαν</span> <span class=\"greek\">ποιεῖν</span>). <span class=\"greek\">τῇ</span> <span class=\"greek\">πυρώσει</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">πειρασμὸν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">γινομένῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:12</a>.—Após adjetivos e particípios: para <span class=\"greek\">ἀγαθὸς</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">οἰκοδομήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:29</a> (<span class=\"greek\">ἀγ</span>. 1a) <span class=\"greek\">ἀδόκιμος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:16</a>. <span class=\"greek\">ἀνεύθετος</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">παραχειμασίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:12</a>. <span class=\"greek\">γεγυμνασμένος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:14</a>. <span class=\"greek\">δυνατός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:4</a>. <span class=\"greek\">ἐξηρτισμένος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:17</a>. <span class=\"greek\">ἕτοιμος</span> (v. esse verbete b) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:15</a>. <span class=\"greek\">ἱκανός</span> (v. esse verbete 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:16</a>. <span class=\"greek\">ὠφέλιμος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:8ab</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:16</a>.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. do resultado que decorre de um conjunto de circunstâncias (de modo que) <span class=\"greek\">πάντα</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">οἰκοδομὴν</span> <span class=\"greek\">γινέσθω</span> tudo deve ser feito de modo que contribua para a edificação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:26</a>; cf. v. 12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:23</a> (mas v. e<span class=\"greek\">δ</span> abaixo); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:7</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">βλέπων</span> <span class=\"greek\">γυναῖκα</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐπιθυμῆσαι</span> <span class=\"greek\">αὐτήν</span> aquele que olha para uma mulher com desejo pecaminoso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:28</a>, mas v. e<span class=\"greek\">ε</span> abaixo. <span class=\"greek\">λευκαί</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">θερισμόν</span> eles (os campos) estão brancos, de modo que a colheita pode começar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:35</a>. <span class=\"greek\">αὕτη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀσθένεια</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">θάνατον</span> esta doença não é da espécie que conduzirá à morte 11:4. Cf. <span class=\"greek\">ἁμαρτία</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">θάνατον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:16f</a>.</p><p class=\"entry-text\">ⓓ de relação (hostil ou amistosa): contra, a favor de</p><p class=\"entry-text\"><span class=\"greek\">α</span>. hostil: contra, com, após verbos de disputa etc.; v. <span class=\"greek\">ἀνταγωνίζομαι</span>, <span class=\"greek\">γογγύζω</span>, <span class=\"greek\">διακρίνομαι</span> (<span class=\"greek\">διακρίνω</span> 5b), <span class=\"greek\">διαλέγομαι</span> 1, <span class=\"greek\">πικραίνομαι</span> (<span class=\"greek\">πικραίνω</span> 2), <span class=\"greek\">στασιάζω</span>, <span class=\"greek\">ἔστην</span> (<span class=\"greek\">ἵστημι</span> B3). <span class=\"greek\">ἐστίν</span> <span class=\"greek\">τινι</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πάλη</span> <span class=\"greek\">πρός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:12</a>. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τι</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> ter algo (a alegar) contra alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:19</a>. <span class=\"greek\">μομφὴν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:13</a>. <span class=\"greek\">πρᾶγμα</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:1</a> (<span class=\"greek\">πρᾶγμα</span> 4). <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">γογγυσμὸς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἑλληνιστῶν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">Ἑβραίους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:1</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">στόμα</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ἀνέῳγεν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὑμᾶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:11</a> (<span class=\"greek\">ἀνοίγω</span> 7). <span class=\"greek\">ἐν</span> <span class=\"greek\">ἔχθρᾳ</span> <span class=\"greek\">ὄντες</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">αὐτούς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:12</a>. <span class=\"greek\">βλασφημίαι</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:6</a> (cf. TestJob 25:10 <span class=\"greek\">εἰπὲ</span> <span class=\"greek\">ἓν</span> <span class=\"greek\">ῥῆμα</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>). <span class=\"greek\">ἀσύμφωνοι</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">ἀλλήλους</span> incapazes de concordar entre si <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:25</a> (Tat. 25, 2); cf. a estrutura de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:23</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. amistosa: para, em direção a, com, perante <span class=\"greek\">ἐργάζεσθαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀγαθόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:10ab</a> (<span class=\"greek\">ἐργάζομαι</span> 2a). <span class=\"greek\">μακροθυμεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:14</a>. <span class=\"greek\">εἰρήνην</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">πρὸ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:1</a> (v. <span class=\"greek\">εἰρήνη</span> 2b). <span class=\"greek\">παρρησίαν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:21</a>; cf. 5:14. <span class=\"greek\">πίστιν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κύριον</span> <span class=\"greek\">Ἰ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHM.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Phlm 5</a>. <span class=\"greek\">πεποίθησιν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:4</a>. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">χάριν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὅλον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λαόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.47\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:47</a> (FCheetham, ET 74, ’63, 214f). <span class=\"greek\">πραΰτητα</span> <span class=\"greek\">ἐνδείκνυσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:2</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">σοφίᾳ</span> <span class=\"greek\">περιπατεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:5</a>. <span class=\"greek\">ἤπιον</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">πάντας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:24</a>.—Após substantivos: <span class=\"greek\">πίστις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:8</a> (cf. 4 Macc 15:24; Just., D. 121, 2); <span class=\"greek\">παρρησία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:4</a>; <span class=\"greek\">κοινωνία</span> 6:14; <span class=\"greek\">συμφώνησις</span> v. 15 (cf. Is 7:2).</p><p class=\"entry-text\">ⓔ para indicar uma conexão, assinalando um ponto de referência: com referência/relação a</p><p class=\"entry-text\"><span class=\"greek\">α</span>. com referência a (Ocellus Luc. c. 42 <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἡμᾶς</span>=com referência a nós) <span class=\"greek\">ἔγνωσαν</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παραβολὴν</span> <span class=\"greek\">εἶπεν</span> reconheceram que ele havia proferido a parábola com referência a eles <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:19</a>; cf. 12:41 (Vita Aesopi cod. G 98 P. <span class=\"greek\">οἱ</span> <span class=\"greek\">Σάμιοι</span> <span class=\"greek\">νοήσαντες</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">εἰρῆσθαι</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">λόγους</span>; Just., D. 122, 3 <span class=\"greek\">ταῦτα</span> … <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">χριστὸν</span> … <span class=\"greek\">εἴρηται</span>). <span class=\"greek\">ἔλεγεν</span> <span class=\"greek\">παραβολὴν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δεῖν</span> <span class=\"greek\">προσεύχεσθαι</span> contou-lhes uma parábola acerca da necessidade de orar 18:1 (Just., D. 90, 5 <span class=\"greek\">σύμβολον</span> … <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">χριστόν</span>). <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">ἔγνω</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τί</span> <span class=\"greek\">εἶπεν</span> <span class=\"greek\">αὐτῷ</span> ninguém entendeu a respeito de quê (=por que) ele lhe disse (isso) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:28</a>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σκληροκαρδίαν</span> <span class=\"greek\">ὑμῶν</span> com referência à (isto é, por causa da) vossa perversidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:5</a> (Just., D. 45, 3). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:21a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:7f</a>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀπεκρίθη</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">ἓν</span> <span class=\"greek\">ῥῆμα</span> não lhe respondeu uma única palavra a respeito de coisa alguma <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:14</a> (v. <span class=\"greek\">ἀποκρίνομαι</span> 1). <span class=\"greek\">ἀνταποκριθῆναι</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ταῦτα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:6</a> (v. <span class=\"greek\">ἀνταποκρίνομαι</span>). <span class=\"greek\">ἀπρόσκοπον</span> <span class=\"greek\">συνείδησιν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> ter uma consciência limpa com respeito a Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:16</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. no que diz respeito a …, com relação a (Maximus Tyr. 31, 3b) <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πληροφορίαν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐλπίδος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:11</a>. <span class=\"greek\">συνιστάνοντες</span> <span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">συνείδησιν</span> <span class=\"greek\">ἀνθρώπων</span> recomendamos a nós mesmos no que diz respeito a toda consciência humana = a toda consciência humana (<span class=\"greek\">πρός</span> com acus. também equivale simplesmente ao dativo; v. Mayser II/2 p. 359) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:2</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> aquilo que diz respeito a Deus ou, como acus. adverbial, com referência ao que diz respeito a Deus (Soph., Phil. 1441; X., De Rep. Lac. 13, 11; Ps.-Isocr. 1, 13 <span class=\"greek\">εὐσεβεῖν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεούς</span>; SIG 204, 51f; 306, 38; Mitt-Wilck. I/2, 109, 3 <span class=\"greek\">εὐσεβὴς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">θεούς</span>; Ex 4:16; 18:19; Jos., Ant. 9, 236) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:17</a>; 5:1. <span class=\"greek\">τὰ</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τι</span> aquilo que pertence a algo; aquilo que é necessário para algo (Plut., Mor. 109b; Jos., Ant. 12, 405 <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">μάχην</span>; 14, 27; termo corrente em documentos oficiais) <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἀπαρτισμόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:28</a> v.l. <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">εἰρήνην</span> (TestJud 9) v. 32; aquilo que contribui para a paz 19:42. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:3</a>.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. elipticamente <span class=\"greek\">τί</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἡμᾶς</span> (subent. <span class=\"greek\">ἐστιν</span>); que nos importa isso? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:4</a>. <span class=\"greek\">τί</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">σέ</span>; em que isso te diz respeito? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:22f</a> (cf. Epict. 4, 1, 10 <span class=\"greek\">τί</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">σέ</span>; Plut., Mor. 986b; Vi. Aesopi I 14 p. 265, 4 Eberh. <span class=\"greek\">τί</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἐμέ</span>; ApcMos 11 <span class=\"greek\">οὐ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πλεονεξία</span> <span class=\"greek\">σου</span>).</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. de acordo com <span class=\"greek\">ὀρθοποδεῖν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀλήθειαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:14</a>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κένωμα</span> de acordo com o vazio Hm 11:3. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θέλημα</span> de acordo com a vontade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:47</a>; Hs 9, 5, 2. <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">ἔπραξεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:10</a>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὅ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:4</a>.—Em comparação com, para ser comparado a (Pind., Hdt. et al.; Ps.-Luc., Halc. 3 <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">αἰῶνα</span>=[a vida é breve] em comparação com toda a eternidade; Sir 25:19; TestJob 18:8; 23:8; Just., D. 19, 2 <span class=\"greek\">οὐδὲν</span> … <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">βάπτισμα</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">ἐστι</span>; Tat. 29, 1 <span class=\"greek\">ὀρθοποδεῖν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀλήθειαν</span>) <span class=\"greek\">ἄξια</span> <span class=\"greek\">πρός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:18</a> (RLeaney, ET 64, ’52f; 92 interpreta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:23</a> à luz deste uso). Cf. IMg 12.</p><p class=\"entry-text\"><span class=\"greek\">ε</span>. exprimindo propósito <span class=\"greek\">πρὸς</span> <span class=\"greek\">τό</span> com inf. (v. Mayser II/1 p. 331f) a fim de, com o propósito de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:19</a> v.l. Talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:28</a> (v. c<span class=\"greek\">γ</span> acima).</p><p class=\"entry-text\">ⓕ em expressões adverbiais (cf. <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὀργήν</span> = <span class=\"greek\">ὀργίλως</span> Soph., Elect. 369; Jos., Bell. 2, 534. <span class=\"greek\">πρὸς</span> <span class=\"greek\">βίαν</span> = <span class=\"greek\">βιαίως</span> Aeschyl., Prom. 208, 353, Eum. 5; Menand., Sam. 559 S. [214 Kö.]; Philo, Spec. Leg. 3, 3. <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἡδονήν</span> Jos., Ant. 7, 195; 12, 398; Just., A II, 3, 2 <span class=\"greek\">πρὸς</span> <span class=\"greek\">χάριν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡδονὴν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πολλῶν</span>) <span class=\"greek\">πρὸς</span> <span class=\"greek\">φθόνον</span> provavelmente=<span class=\"greek\">φθονερῶς</span> com ciúme <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:5</a> (v. <span class=\"greek\">φθόνος</span>, onde se encontra a bibliografia). <span class=\"greek\">πρὸς</span> <span class=\"greek\">εὐφρασίαν</span> com alegria AcPl Ox 6, 9f (cf. Aa 1 p. 241, 1 <span class=\"greek\">ὑπερευφραινομένη</span>).</p><p class=\"entry-text\">ⓖ junto de, em, perto de <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> <span class=\"greek\">εἶναι</span> estar (na companhia) de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.56\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:56</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:3</a>; 9:19a; 14:49; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:1f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:5</a>; 3:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:2</a>. <span class=\"greek\">διαμένειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.48\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:48</a> D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:5b</a>. <span class=\"greek\">ἐπιμένειν</span> 1:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:7</a>. <span class=\"greek\">παραμένειν</span> 16:6 (v.l. <span class=\"greek\">κατα</span>-). <span class=\"greek\">μένειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:3</a> D. <span class=\"greek\">παρεῖναι</span> 12:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:18</a>, 20; cf. <span class=\"greek\">παρουσία</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὑμᾶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:26</a>. <span class=\"greek\">παρεπιδημεῖν</span> 1 Cl 1:2. <span class=\"greek\">ἐποίησεν</span> <span class=\"greek\">τρεῖς</span> <span class=\"greek\">μῆνας</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Ἐλισάβεδ</span> GJs 12:3. <span class=\"greek\">πρὸς</span> <span class=\"greek\">σὲ</span> <span class=\"greek\">ποιῶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πάσχα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:18b</a>. Cf. também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:12</a>; 7:12; 12:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHM.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Phlm 13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:1</a>; Hm 11:9b v.l.—<span class=\"greek\">πρὸς</span> <span class=\"greek\">ἑαυτούς</span> entre si ou consigo mesmos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:10</a> (caso <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἑ</span>. se ligue a <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">ἐκράτησαν</span>; B-D-F §239, 1). <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">προσηύχετο</span> proferiu uma oração consigo mesmo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:11</a>. Cf. 24:12.—<span class=\"greek\">δεδεμένον</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">θύραν</span> amarrado junto a uma porta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:4</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἡδονὴν</span> <span class=\"greek\">ἐδέσμευεν</span> (Satanás) prendeu toda a humanidade à satisfação dos próprios prazeres AcPlCor 2:11. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θάλασσαν</span> à beira-mar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:1b</a>. Sobre <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> junto ao fogo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.54\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:54</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.56\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:56</a> v. B-D-F §239, 3; Rob. 625 (talvez com a ideia de voltar-se para o fogo; v. também 4 Km 23:3). <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἓν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὀρέων</span> junto a um dos montes 1 Cl 10:7. <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">θύραν</span> o lugar próximo da porta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:2</a>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">γράμμα</span> letra por letra Hv 2, 1, 4.—Sobre termos <span class=\"greek\">πρός</span> <span class=\"greek\">τι</span> v. PWouters, The Treatment of Relational Nouns in Ancient Grammar: Orbis 38, ’95, 149–78 (bibliografia). M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0302-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσάββατον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσάββατον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Jdth 8:6; Ps 91:1 S; Ps 92:1; Bull. de l’Inst. franç. d’Archéol. orient. 30, ’31, pp. 4–6) o dia anterior ao sábado, isto é, sexta-feira, empregado para explicar a palavra <span class=\"greek\">παρασκευή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:42</a>. Também no Fgm. do Diatessaron de Dura (CKraeling, A Gk. Fgm. of Tatian’s Diatessaron fr. Dura: Studies and Documents [ed. KLake and SLake] III ’35; v. ASyn. 348, 30).—DELG s.v. <span class=\"greek\">σάββατα</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0302-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσαγορεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσαγορεύω</span> fut. 2.ª sg. <span class=\"greek\">προσαγορεύσεις</span> Dt 23:7; 1.º aor. <span class=\"greek\">προσηγόρευσα</span>. Pass.: 1.º aor. <span class=\"greek\">προσηγορεύθην</span>; perf. 3.ª sg. <span class=\"greek\">προσηγόρευται</span>; mais-que-perf. 3.ª sg. <span class=\"greek\">προσηγόρευτο</span> (Just.).</p><p class=\"entry-text\">① dirigir uma saudação, saudar (Aeschyl., Hdt. et al.; OGI 771, 48; freq. em pap; cf. Dt 23:7? [com dat. como JosAs 7:9]) <span class=\"greek\">τινά</span> alguém MPol 20:2ab.</p><p class=\"entry-text\">② referir-se a alguém pelo nome ou por outro termo, chamar, nomear, designar (X., Pla. et al.; ins, pap, LXX; TestSol 6:2; TestLevi 16:3; AscIs 3:10) com acus. de objeto e também de predicativo (X., Mem. 3, 2, 1; Plut., Aem. 258 [8, 3]; ins; Wsd 14:22; 2 Macc 1:36) de Cristo como dispensador de numerosos benefícios <span class=\"greek\">υἱοὺς</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">προσηγόρευσεν</span> dirigiu-se a nós como um pai a seus filhos 2 Cl 1:4. Pass. (Pla. et al.; Diod S 1, 4, 7; 13, 98, 3; 40, 3, 3; 1 Macc 14:40; 2 Macc 4:7; 14:37; Demetr.: 722 Fgm. 1, 3 Jac.; Philo, Agr. 66, Abrah. 121, Mos. 2, 109; 112; Jos., Bell. 3, 35, Ant. 15, 293, C. Ap. 1, 250) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:10</a>. De Abraão <span class=\"greek\">φίλος</span> <span class=\"greek\">προσηγορεύθη</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> 1 Cl 17:2; cf. 10:1 (v. <span class=\"greek\">Ἀβραάμ</span> e <span class=\"greek\">φίλος</span> 2a<span class=\"greek\">β</span>).—DELG s.v. <span class=\"greek\">ἀγορά</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0302-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσάγω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσάγω</span> 2.º aor. <span class=\"greek\">προσήγαγον</span>, imper. <span class=\"greek\">προσάγαγε</span>, inf. <span class=\"greek\">προσαγαγεῖν</span>; perf. 3.ª pl. <span class=\"greek\">προσαγειόχασιν</span> Lev 10:19. Pass.: imperf. <span class=\"greek\">προσηγόμην</span>; 1.º fut. 3.ª sg. <span class=\"greek\">προσαχθήσεται</span> Lev 14:2; 1.º aor. <span class=\"greek\">προσήχθην</span> (Hom.+; ins, pap, LXX, EpArist, Philo, Joseph., Test12Patr, apolog.).</p><p class=\"entry-text\">① trans. levar à presença de alguém, conduzir (à frente)</p><p class=\"entry-text\">ⓐ lit. <span class=\"greek\">τινά</span> alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:6</a> v.l.; B 13:5a. Pass. MPol 9:1f. <span class=\"greek\">προσάγαγε</span> <span class=\"greek\">ὧδε</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">υἱόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:41</a>. Com acus. a suprir <span class=\"greek\">Ἰωσὴφ</span> <span class=\"greek\">προσήγαγεν</span> (<span class=\"greek\">αὐτόν</span>) <span class=\"greek\">εἰς</span> … B 13:5b (<span class=\"greek\">πρ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> Herodian 1, 5, 1). <span class=\"greek\">τινά</span> <span class=\"greek\">τινι</span> conduzir alguém a alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:20</a>; B 13:4 (Gen 48:9); pass. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:24</a> v.l.</p><p class=\"entry-text\">ⓑ fig.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. de Cristo, que conduz as pessoas a Deus (X., Cyr. 1, 3, 8 da admissão a uma audiência com o Grande Rei) <span class=\"greek\">ἵνα</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">προσαγάγῃ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:18</a> (Just., D. 2, 1 al.; Jos., Ant. 14, 272 a voz média transmite o sentido de ‘negociar a paz’, ‘reconciliar’).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. como termo técnico do procedimento sacrificial (Hdt. 3, 24 et al.; LXX; EpArist 45 <span class=\"greek\">π</span>. <span class=\"greek\">θυσίας</span>) levar, apresentar, de Isaque <span class=\"greek\">προσήγετο</span> <span class=\"greek\">θυσία</span> 1 Cl 31:3. <span class=\"greek\">προσάξω</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">δῶρον</span> <span class=\"greek\">κυρίῳ</span> apresentá-la-ei (a criança, Maria) ao Senhor como dádiva GJs 4:1. <span class=\"greek\">τὴν</span> <span class=\"greek\">θρησκείαν</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">αὐτῷ</span> (=<span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>) oferecer culto (ritual) a Deus Dg 3:2 (cf. Tob 12:12; Ath. 13, 2). Em uso absoluto <span class=\"greek\">ὀφείλομεν</span> <span class=\"greek\">πλουσιώτερον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὑψηλότερον</span> <span class=\"greek\">προσάγειν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">φόβῳ</span> <span class=\"greek\">αὐτοῦ</span> devemos sacrificar tanto mais abundantemente e generosamente por temor de (Deus) B 1:7; mas v. 2b.</p><p class=\"entry-text\">② intr. mover-se em direção a um ponto de referência, chegar perto, aproximar-se (Theocr. et al.; Plut., Mor. 800a, Pomp. 643 [46, 1]; SIG 1042, 3; PTebt 47, 15; Josh 3:9; 1 Km 9:18; 3 Km 18:30ab; Sir 12:13; 2 Macc 6:19; EpArist 59; Jos., Ant. 6, 52.—Anz 335).</p><p class=\"entry-text\">ⓐ lit. <span class=\"greek\">ὑπενόουν</span> <span class=\"greek\">προσάγειν</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">χώραν</span> suspeitavam que havia terra próxima (lit. ‘aproximando-se deles’) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:27</a> (vv.ll. <span class=\"greek\">προσανέχειν</span>, <span class=\"greek\">προσεγγίζειν</span>, <span class=\"greek\">προσαχεῖν</span>).</p><p class=\"entry-text\">ⓑ fig., de pessoas que se aproximam de Deus B 2:9. <span class=\"greek\">προσάγειν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">φόβῳ</span> <span class=\"greek\">αὐτοῦ</span> (= <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>) aproximar-se (do temor) de Deus 1:7, a menos que <span class=\"greek\">πρ</span>. signifique aqui apresentar uma oferta (assim Lghtf. et al.; v. 1b<span class=\"greek\">β</span>).—M-M. TW.</p></section></article>"};
